package com.objectnamemarker;

import java.awt.Color;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

final class ConfigSet
{
	private final String id;
	private volatile String name;
	private volatile boolean enabled;
	private volatile String hullObjectNames;
	private volatile String outlineObjectNames;
	private volatile String tileObjectNames;
	private volatile Color hullColor;
	private volatile Color outlineColor;
	private volatile Color tileFillColor;
	private volatile Color tileBorderColor;
	private volatile int borderThickness;
	private volatile boolean fadeTileOpacity;
	private volatile Set<Integer> hiddenHullIds;
	private volatile Set<Integer> hiddenOutlineIds;
	private volatile Set<Integer> hiddenTileIds;
	private volatile Set<String> parsedHullNames;
	private volatile Set<String> parsedOutlineNames;
	private volatile Set<String> parsedTileNames;

	private ConfigSet(String id, String name)
	{
		this.id = id;
		this.name = name == null ? "" : name;
		this.enabled = true;
		this.hullObjectNames = "";
		this.outlineObjectNames = "";
		this.tileObjectNames = "";
		this.hullColor = new Color(0, 255, 0, 50);
		this.outlineColor = new Color(0, 255, 0);
		this.tileFillColor = new Color(0, 255, 0, 50);
		this.tileBorderColor = new Color(0, 255, 0, 0);
		this.borderThickness = 1;
		this.fadeTileOpacity = false;
		this.hiddenHullIds = Collections.emptySet();
		this.hiddenOutlineIds = Collections.emptySet();
		this.hiddenTileIds = Collections.emptySet();
		this.parsedHullNames = Collections.emptySet();
		this.parsedOutlineNames = Collections.emptySet();
		this.parsedTileNames = Collections.emptySet();
	}

	static ConfigSet createDefault(String name)
	{
		return new ConfigSet(UUID.randomUUID().toString(), name);
	}

	static ConfigSet create(String id, String name)
	{
		String setId = id == null || id.trim().isEmpty() ? UUID.randomUUID().toString() : id;
		return new ConfigSet(setId, name);
	}

	String getId()
	{
		return id;
	}

	String getName()
	{
		return name;
	}

	void setName(String name)
	{
		this.name = name == null ? "" : name;
	}

	boolean isEnabled()
	{
		return enabled;
	}

	void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	String getHullObjectNames()
	{
		return hullObjectNames;
	}

	void setHullObjectNames(String hullObjectNames)
	{
		this.hullObjectNames = hullObjectNames == null ? "" : hullObjectNames;
		parsedHullNames = ObjectNameMarkerParser.parseNames(this.hullObjectNames);
	}

	String getOutlineObjectNames()
	{
		return outlineObjectNames;
	}

	void setOutlineObjectNames(String outlineObjectNames)
	{
		this.outlineObjectNames = outlineObjectNames == null ? "" : outlineObjectNames;
		parsedOutlineNames = ObjectNameMarkerParser.parseNames(this.outlineObjectNames);
	}

	String getTileObjectNames()
	{
		return tileObjectNames;
	}

	void setTileObjectNames(String tileObjectNames)
	{
		this.tileObjectNames = tileObjectNames == null ? "" : tileObjectNames;
		parsedTileNames = ObjectNameMarkerParser.parseTileNames(this.tileObjectNames);
	}

	Color getHullColor()
	{
		return hullColor;
	}

	void setHullColor(Color hullColor)
	{
		if (hullColor != null)
		{
			this.hullColor = hullColor;
		}
	}

	Color getOutlineColor()
	{
		return outlineColor;
	}

	void setOutlineColor(Color outlineColor)
	{
		if (outlineColor != null)
		{
			this.outlineColor = outlineColor;
		}
	}

	Color getTileFillColor()
	{
		return tileFillColor;
	}

	void setTileFillColor(Color tileFillColor)
	{
		if (tileFillColor != null)
		{
			this.tileFillColor = tileFillColor;
		}
	}

	Color getTileBorderColor()
	{
		return tileBorderColor;
	}

	void setTileBorderColor(Color tileBorderColor)
	{
		if (tileBorderColor != null)
		{
			this.tileBorderColor = tileBorderColor;
		}
	}

	int getBorderThickness()
	{
		return borderThickness;
	}

	void setBorderThickness(int borderThickness)
	{
		this.borderThickness = Math.max(1, borderThickness);
	}

	boolean isFadeTileOpacity()
	{
		return fadeTileOpacity;
	}

	void setFadeTileOpacity(boolean fadeTileOpacity)
	{
		this.fadeTileOpacity = fadeTileOpacity;
	}

	boolean hasActiveNames()
	{
		return enabled
			&& (!parsedHullNames.isEmpty() || !parsedOutlineNames.isEmpty() || !parsedTileNames.isEmpty());
	}

	boolean matches(HighlightKind kind, String normalizedName)
	{
		return enabled && normalizedName != null && names(kind).contains(normalizedName);
	}

	boolean isDisplayed(HighlightKind kind, int id)
	{
		return !hidden(kind).contains(id);
	}

	void setDisplayed(HighlightKind kind, int id, boolean displayed)
	{
		Set<Integer> next = new HashSet<>(hidden(kind));

		if (displayed)
		{
			next.remove(id);
		}
		else
		{
			next.add(id);
		}

		setHidden(kind, next);
	}

	void clearHidden(HighlightKind kind)
	{
		setHidden(kind, Collections.emptySet());
	}

	Set<Integer> hiddenIds(HighlightKind kind)
	{
		return hidden(kind);
	}

	void setHiddenIds(HighlightKind kind, Collection<Integer> ids)
	{
		Set<Integer> next = new HashSet<>();

		if (ids != null)
		{
			for (Integer id : ids)
			{
				if (id != null)
				{
					next.add(id);
				}
			}
		}

		setHidden(kind, next);
	}

	private Set<String> names(HighlightKind kind)
	{
		switch (kind)
		{
			case HULL:
				return parsedHullNames;
			case OUTLINE:
				return parsedOutlineNames;
			case TILE:
				return parsedTileNames;
			default:
				return Collections.emptySet();
		}
	}

	private Set<Integer> hidden(HighlightKind kind)
	{
		switch (kind)
		{
			case HULL:
				return hiddenHullIds;
			case OUTLINE:
				return hiddenOutlineIds;
			case TILE:
				return hiddenTileIds;
			default:
				return Collections.emptySet();
		}
	}

	private void setHidden(HighlightKind kind, Set<Integer> ids)
	{
		Set<Integer> stored = ids.isEmpty() ? Collections.emptySet() : Collections.unmodifiableSet(ids);

		switch (kind)
		{
			case HULL:
				hiddenHullIds = stored;
				break;
			case OUTLINE:
				hiddenOutlineIds = stored;
				break;
			case TILE:
				hiddenTileIds = stored;
				break;
			default:
				break;
		}
	}
}

package com.objectnamemarker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

final class ConfigSetCodec
{
	static final class Loaded
	{
		final int selectedIndex;
		final List<ConfigSet> sets;

		private Loaded(int selectedIndex, List<ConfigSet> sets)
		{
			this.selectedIndex = selectedIndex;
			this.sets = sets;
		}
	}

	private ConfigSetCodec()
	{
	}

	static String write(Gson gson, int selectedIndex, List<ConfigSet> sets)
	{
		Document document = new Document();
		document.selected = selectedIndex;
		document.sets = new ArrayList<>();

		for (ConfigSet set : sets)
		{
			document.sets.add(toDto(set));
		}

		return gson.toJson(document);
	}

	static Loaded read(Gson gson, String json)
	{
		Document document;

		try
		{
			document = gson.fromJson(json, Document.class);
		}
		catch (JsonSyntaxException ex)
		{
			throw new IllegalArgumentException("Could not read config sets", ex);
		}

		if (document == null || document.sets == null)
		{
			throw new IllegalArgumentException("Could not read config sets");
		}

		List<ConfigSet> sets = new ArrayList<>();

		for (SetDto dto : document.sets)
		{
			if (dto != null)
			{
				sets.add(fromDto(dto));
			}
		}

		return new Loaded(document.selected, sets);
	}

	static ConfigSet fromLegacy(
		String hullObjectNames,
		String outlineObjectNames,
		String tileObjectNames,
		String hullColor,
		String outlineColor,
		String tileFillColor,
		String tileBorderColor,
		String borderThickness,
		String fadeTileOpacity
	)
	{
		ConfigSet set = ConfigSet.createDefault("Config set 1");
		set.setHullObjectNames(hullObjectNames);
		set.setOutlineObjectNames(outlineObjectNames);
		set.setTileObjectNames(tileObjectNames);
		set.setHullColor(parseLegacyColor(hullColor, set.getHullColor()));
		set.setOutlineColor(parseLegacyColor(outlineColor, set.getOutlineColor()));
		set.setTileFillColor(parseLegacyColor(tileFillColor, set.getTileFillColor()));
		set.setTileBorderColor(parseLegacyColor(tileBorderColor, set.getTileBorderColor()));
		set.setBorderThickness(parseLegacyInt(borderThickness, set.getBorderThickness()));
		set.setFadeTileOpacity("true".equalsIgnoreCase(fadeTileOpacity));
		return set;
	}

	private static SetDto toDto(ConfigSet set)
	{
		SetDto dto = new SetDto();
		dto.id = set.getId();
		dto.name = set.getName();
		dto.enabled = set.isEnabled();
		dto.hullObjectNames = set.getHullObjectNames();
		dto.outlineObjectNames = set.getOutlineObjectNames();
		dto.tileObjectNames = set.getTileObjectNames();
		dto.hullColor = set.getHullColor().getRGB();
		dto.outlineColor = set.getOutlineColor().getRGB();
		dto.tileFillColor = set.getTileFillColor().getRGB();
		dto.tileBorderColor = set.getTileBorderColor().getRGB();
		dto.borderThickness = set.getBorderThickness();
		dto.fadeTileOpacity = set.isFadeTileOpacity();
		dto.hiddenHullIds = new ArrayList<>(set.hiddenIds(HighlightKind.HULL));
		dto.hiddenOutlineIds = new ArrayList<>(set.hiddenIds(HighlightKind.OUTLINE));
		dto.hiddenTileIds = new ArrayList<>(set.hiddenIds(HighlightKind.TILE));
		return dto;
	}

	private static ConfigSet fromDto(SetDto dto)
	{
		ConfigSet set = ConfigSet.create(dto.id, dto.name == null ? "Config set" : dto.name);
		set.setEnabled(dto.enabled == null || dto.enabled);
		set.setHullObjectNames(dto.hullObjectNames);
		set.setOutlineObjectNames(dto.outlineObjectNames);
		set.setTileObjectNames(dto.tileObjectNames);
		set.setHullColor(colorOrDefault(dto.hullColor, set.getHullColor()));
		set.setOutlineColor(colorOrDefault(dto.outlineColor, set.getOutlineColor()));
		set.setTileFillColor(colorOrDefault(dto.tileFillColor, set.getTileFillColor()));
		set.setTileBorderColor(colorOrDefault(dto.tileBorderColor, set.getTileBorderColor()));
		set.setBorderThickness(dto.borderThickness == null ? 1 : dto.borderThickness);
		set.setFadeTileOpacity(Boolean.TRUE.equals(dto.fadeTileOpacity));
		set.setHiddenIds(HighlightKind.HULL, dto.hiddenHullIds);
		set.setHiddenIds(HighlightKind.OUTLINE, dto.hiddenOutlineIds);
		set.setHiddenIds(HighlightKind.TILE, dto.hiddenTileIds);
		return set;
	}

	private static Color colorOrDefault(Integer rgb, Color fallback)
	{
		if (rgb == null)
		{
			return fallback;
		}

		return new Color(rgb, true);
	}

	// RuneLite stores a Color config value as String.valueOf(color.getRGB()).
	private static Color parseLegacyColor(String stored, Color fallback)
	{
		if (stored == null || stored.trim().isEmpty())
		{
			return fallback;
		}

		try
		{
			return new Color(Integer.parseInt(stored.trim()), true);
		}
		catch (NumberFormatException ex)
		{
			return fallback;
		}
	}

	private static int parseLegacyInt(String stored, int fallback)
	{
		if (stored == null || stored.trim().isEmpty())
		{
			return fallback;
		}

		try
		{
			return Integer.parseInt(stored.trim());
		}
		catch (NumberFormatException ex)
		{
			return fallback;
		}
	}

	private static final class Document
	{
		private int selected;
		private List<SetDto> sets;
	}

	private static final class SetDto
	{
		private String id;
		private String name;
		private Boolean enabled;
		private String hullObjectNames;
		private String outlineObjectNames;
		private String tileObjectNames;
		private Integer hullColor;
		private Integer outlineColor;
		private Integer tileFillColor;
		private Integer tileBorderColor;
		private Integer borderThickness;
		private Boolean fadeTileOpacity;
		private List<Integer> hiddenHullIds;
		private List<Integer> hiddenOutlineIds;
		private List<Integer> hiddenTileIds;
	}
}

