package com.objectnamemarker;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

final class ConfigSetList
{
	private volatile List<ConfigSet> sets = new CopyOnWriteArrayList<>();
	private volatile int selectedIndex = -1;

	List<ConfigSet> getSets()
	{
		return sets;
	}

	int getSelectedIndex()
	{
		return selectedIndex;
	}

	ConfigSet getSelected()
	{
		List<ConfigSet> current = sets;
		int index = selectedIndex;

		if (index < 0 || index >= current.size())
		{
			return null;
		}

		return current.get(index);
	}

	void replace(List<ConfigSet> next, int selected)
	{
		List<ConfigSet> current = new CopyOnWriteArrayList<>(next);
		sets = current;

		if (current.isEmpty())
		{
			selectedIndex = -1;
		}
		else if (selected < 0 || selected >= current.size())
		{
			selectedIndex = 0;
		}
		else
		{
			selectedIndex = selected;
		}
	}

	void setSelectedIndex(int index)
	{
		if (index >= 0 && index < sets.size())
		{
			selectedIndex = index;
		}
	}

	int indexOf(ConfigSet set)
	{
		return sets.indexOf(set);
	}

	ConfigSet addSet()
	{
		ConfigSet set = ConfigSet.createDefault(nextName(sets));
		sets.add(set);
		selectedIndex = sets.size() - 1;
		return set;
	}

	ConfigSet removeSelected()
	{
		int index = selectedIndex;
		List<ConfigSet> current = sets;

		if (index < 0 || index >= current.size())
		{
			return null;
		}

		ConfigSet removed = current.remove(index);

		if (current.isEmpty())
		{
			selectedIndex = -1;
		}
		else if (index >= current.size())
		{
			selectedIndex = current.size() - 1;
		}

		return removed;
	}

	static String nextName(List<ConfigSet> sets)
	{
		int number = 1;

		while (true)
		{
			String candidate = "Config set " + number;
			boolean used = false;

			for (ConfigSet set : sets)
			{
				if (candidate.equals(set.getName()))
				{
					used = true;
					break;
				}
			}

			if (!used)
			{
				return candidate;
			}

			number++;
		}
	}

	List<ConfigSet> snapshot()
	{
		return new ArrayList<>(sets);
	}
}

package com.objectnamemarker;

enum HighlightKind
{
	HULL("Object hull highlight"),
	OUTLINE("Object outline highlight"),
	TILE("Object tile highlight");

	private final String title;

	HighlightKind(String title)
	{
		this.title = title;
	}

	String getTitle()
	{
		return title;
	}
}

package com.objectnamemarker;

import java.util.ArrayList;
import java.util.List;

final class HighlightPlan
{
	static final class Draw
	{
		final ConfigSet set;
		final HighlightKind kind;

		private Draw(ConfigSet set, HighlightKind kind)
		{
			this.set = set;
			this.kind = kind;
		}
	}

	private HighlightPlan()
	{
	}

	static List<Draw> plan(List<ConfigSet> sets, String normalizedName, int objectId)
	{
		List<Draw> draws = new ArrayList<>();

		for (ConfigSet set : sets)
		{
			for (HighlightKind kind : HighlightKind.values())
			{
				if (set.matches(kind, normalizedName) && set.isDisplayed(kind, objectId))
				{
					draws.add(new Draw(set, kind));
				}
			}
		}

		return draws;
	}
}

