package com.objectnamemarker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;

final class ObjectIdSelections
{
	static final class Entry
	{
		final int id;
		final String name;
		final boolean displayed;

		Entry(int id, String name, boolean displayed)
		{
			this.id = id;
			this.name = name;
			this.displayed = displayed;
		}
	}

	static final class Change
	{
		final String setId;
		final HighlightKind kind;

		Change(String setId, HighlightKind kind)
		{
			this.setId = setId;
			this.kind = kind;
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof Change))
			{
				return false;
			}

			Change change = (Change) other;
			return kind == change.kind && setId.equals(change.setId);
		}

		@Override
		public int hashCode()
		{
			return 31 * setId.hashCode() + kind.hashCode();
		}
	}

	private static final class Bucket
	{
		private final Map<Integer, String> names = new LinkedHashMap<>();
	}

	private final Map<String, Map<HighlightKind, Bucket>> bySet = new HashMap<>();
	private final List<Consumer<Change>> listeners = new ArrayList<>();

	void addListener(Consumer<Change> listener)
	{
		synchronized (this)
		{
			listeners.add(listener);
		}
	}

	void removeListener(Consumer<Change> listener)
	{
		synchronized (this)
		{
			listeners.remove(listener);
		}
	}

	synchronized boolean observe(String setId, HighlightKind kind, int id, String name)
	{
		Bucket bucket = bucket(setId, kind);

		if (bucket.names.containsKey(id))
		{
			return false;
		}

		bucket.names.put(id, name);
		return true;
	}

	synchronized void reset(String setId, HighlightKind kind)
	{
		Map<HighlightKind, Bucket> kinds = bySet.get(setId);

		if (kinds == null)
		{
			return;
		}

		Bucket bucket = kinds.get(kind);

		if (bucket != null)
		{
			bucket.names.clear();
		}
	}

	synchronized void removeSet(String setId)
	{
		bySet.remove(setId);
	}

	synchronized void clear()
	{
		bySet.clear();
	}

	synchronized List<Entry> entries(String setId, HighlightKind kind, Set<Integer> hidden)
	{
		Map<HighlightKind, Bucket> kinds = bySet.get(setId);
		List<Entry> entries = new ArrayList<>();

		if (kinds == null)
		{
			return entries;
		}

		Bucket bucket = kinds.get(kind);

		if (bucket == null)
		{
			return entries;
		}

		for (Map.Entry<Integer, String> entry : bucket.names.entrySet())
		{
			int id = entry.getKey();
			entries.add(new Entry(id, entry.getValue(), hidden == null || !hidden.contains(id)));
		}

		entries.sort(Comparator
			.comparing((Entry entry) -> entry.name, String.CASE_INSENSITIVE_ORDER)
			.thenComparingInt(entry -> entry.id));
		return entries;
	}

	void notifyListeners(Iterable<Change> changes)
	{
		List<Change> changesCopy = new ArrayList<>();

		for (Change change : changes)
		{
			changesCopy.add(change);
		}

		List<Consumer<Change>> listenerCopy;

		synchronized (this)
		{
			listenerCopy = new ArrayList<>(listeners);
		}

		SwingUtilities.invokeLater(() ->
		{
			for (Change change : changesCopy)
			{
				for (Consumer<Change> listener : listenerCopy)
				{
					listener.accept(change);
				}
			}
		});
	}

	private Bucket bucket(String setId, HighlightKind kind)
	{
		Map<HighlightKind, Bucket> kinds = bySet.get(setId);

		if (kinds == null)
		{
			kinds = new EnumMap<>(HighlightKind.class);
			bySet.put(setId, kinds);
		}

		Bucket bucket = kinds.get(kind);

		if (bucket == null)
		{
			bucket = new Bucket();
			kinds.put(kind, bucket);
		}

		return bucket;
	}
}

package com.objectnamemarker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("objectnamemarker")
public interface ObjectNameMarkerConfig extends Config
{
	@ConfigItem(
		keyName = "configSets",
		name = "Config sets",
		description = "Saved config sets. Edited from the Super Object Marker side panel.",
		hidden = true,
		position = 0
	)
	default String configSets()
	{
		return "";
	}

	@Range(min = 1, max = 1000)
	@ConfigItem(
		keyName = "maxHighlightedObjects",
		name = "Max highlighted objects",
		description = "Safety limit for the number of matching objects rendered at once, across all enabled config sets.",
		position = 1
	)
	default int maxHighlightedObjects()
	{
		return 20;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
		keyName = "renderDistance",
		name = "Render distance",
		description = "Only render matching objects within this many tiles.",
		position = 2
	)
	default int renderDistance()
	{
		return 32;
	}
}

