import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class ObjectNameMarkerOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 0;

	private final Client client;
	private final ObjectNameMarkerPlugin plugin;
	private final ObjectNameMarkerConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private ObjectNameMarkerOverlay(
		Client client,
		ObjectNameMarkerPlugin plugin,
		ObjectNameMarkerConfig config,
		ModelOutlineRenderer modelOutlineRenderer
	)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player localPlayer = client.getLocalPlayer();

		if (localPlayer == null)
		{
			return null;
		}

		WorldPoint playerLocation = localPlayer.getWorldLocation();
		List<TileObject> objects = new ArrayList<>(plugin.getObjects());
		objects.sort(Comparator.comparingInt(object -> object.getWorldLocation().distanceTo(playerLocation)));
		int rendered = 0;
		List<ConfigSet> sets = plugin.getConfigSets();

		for (TileObject object : objects)
		{
			if (rendered >= config.maxHighlightedObjects())
			{
				break;
			}

			if (object.getWorldLocation().distanceTo(playerLocation) > config.renderDistance())
			{
				continue;
			}

			NamedObject namedObject = plugin.identify(object);

			if (namedObject == null)
			{
				continue;
			}

			List<HighlightPlan.Draw> draws = HighlightPlan.plan(sets, namedObject.name, namedObject.id);

			if (draws.isEmpty())
			{
				continue;
			}

			for (HighlightPlan.Draw draw : draws)
			{
				switch (draw.kind)
				{
					case HULL:
						renderHull(graphics, object, draw.set);
						break;
					case OUTLINE:
						renderModelOutline(object, draw.set);
						break;
					case TILE:
						renderTiles(graphics, object, draw.set);
						break;
					default:
						break;
				}
			}

			rendered++;
		}

		return null;
	}

	private void renderModelOutline(TileObject object, ConfigSet set)
	{
		Color color = set.getOutlineColor();

		if (object instanceof GameObject)
		{
			modelOutlineRenderer.drawOutline((GameObject) object, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
			return;
		}

		if (object instanceof WallObject)
		{
			modelOutlineRenderer.drawOutline((WallObject) object, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
			return;
		}

		if (object instanceof DecorativeObject)
		{
			modelOutlineRenderer.drawOutline((DecorativeObject) object, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
			return;
		}

		if (object instanceof GroundObject)
		{
			modelOutlineRenderer.drawOutline((GroundObject) object, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
		}
	}

	private void renderHull(Graphics2D graphics, TileObject object, ConfigSet set)
	{
		Shape hull = getConvexHull(object);

		if (hull == null)
		{
			return;
		}

		Stroke stroke = new BasicStroke(set.getBorderThickness());
		OverlayUtil.renderPolygon(graphics, hull, set.getHullColor(), set.getHullColor(), stroke);
	}

	private Shape getConvexHull(TileObject object)
	{
		if (object instanceof GameObject)
		{
			return ((GameObject) object).getConvexHull();
		}

		if (object instanceof WallObject)
		{
			return ((WallObject) object).getConvexHull();
		}

		if (object instanceof DecorativeObject)
		{
			return ((DecorativeObject) object).getConvexHull();
		}

		if (object instanceof GroundObject)
		{
			return ((GroundObject) object).getConvexHull();
		}

		return null;
	}

	private void renderTiles(Graphics2D graphics, TileObject object, ConfigSet set)
	{
		if (object instanceof GameObject)
		{
			renderGameObjectTiles(graphics, (GameObject) object, set);
			return;
		}

		renderSingleTileObjectTiles(graphics, object, set);
	}

	private void renderGameObjectTiles(Graphics2D graphics, GameObject object, ConfigSet set)
	{
		WorldPoint base = WorldPoint.fromScene(
			client,
			object.getSceneMinLocation().getX(),
			object.getSceneMinLocation().getY(),
			object.getPlane()
		);

		int objectMinX = base.getX();
		int objectMinY = base.getY();
		int objectMaxX = base.getX() + object.sizeX() - 1;
		int objectMaxY = base.getY() + object.sizeY() - 1;

		renderTileArea(
			graphics,
			objectMinX,
			objectMinY,
			objectMaxX,
			objectMaxY,
			object.sizeX(),
			object.sizeY(),
			object.getPlane(),
			set
		);
	}

	private void renderSingleTileObjectTiles(Graphics2D graphics, TileObject object, ConfigSet set)
	{
		WorldPoint base = object.getWorldLocation();

		renderTileArea(
			graphics,
			base.getX(),
			base.getY(),
			base.getX(),
			base.getY(),
			1,
			1,
			base.getPlane(),
			set
		);
	}

	private void renderTileArea(
		Graphics2D graphics,
		int minX,
		int minY,
		int maxX,
		int maxY,
		int objectWidth,
		int objectHeight,
		int plane,
		ConfigSet set
	)
	{
		CoreRect core = getCoreRect(minX, minY, maxX, maxY);
		boolean canFade = objectWidth >= 3 && objectHeight >= 3;
		int maxDistance = getMaxDistanceFromCore(minX, minY, maxX, maxY, core);
		Stroke stroke = new BasicStroke(set.getBorderThickness());

		for (int x = minX; x <= maxX; x++)
		{
			for (int y = minY; y <= maxY; y++)
			{
				LocalPoint localPoint = LocalPoint.fromWorld(client, new WorldPoint(x, y, plane));

				if (localPoint == null)
				{
					continue;
				}

				Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);

				if (tilePoly == null)
				{
					continue;
				}

				int distanceFromCore = distanceFromRect(x, y, core.minX, core.minY, core.maxX, core.maxY);
				Color fillColor;

				if (canFade)
				{
					fillColor = getTileFillColor(set, distanceFromCore, maxDistance);
				}
				else
				{
					fillColor = set.getTileFillColor();
				}

				OverlayUtil.renderPolygon(
					graphics,
					tilePoly,
					set.getTileBorderColor(),
					fillColor,
					stroke
				);
			}
		}
	}

	private Color getTileFillColor(ConfigSet set, int distanceFromCore, int maxDistance)
	{
		Color base = set.getTileFillColor();

		if (!set.isFadeTileOpacity() || maxDistance <= 0 || distanceFromCore <= 0)
		{
			return base;
		}

		int effectiveMaxDistance = Math.max(maxDistance, 3);
		double t = Math.min(1.0, distanceFromCore / (double) effectiveMaxDistance);
		double alphaMultiplier = 1.0 - (0.5 * t);
		int alpha = (int) Math.round(base.getAlpha() * alphaMultiplier);
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
	}

	private int getMaxDistanceFromCore(int minX, int minY, int maxX, int maxY, CoreRect core)
	{
		int maxDistance = distanceFromRect(minX, minY, core.minX, core.minY, core.maxX, core.maxY);
		maxDistance = Math.max(maxDistance, distanceFromRect(maxX, minY, core.minX, core.minY, core.maxX, core.maxY));
		maxDistance = Math.max(maxDistance, distanceFromRect(minX, maxY, core.minX, core.minY, core.maxX, core.maxY));
		maxDistance = Math.max(maxDistance, distanceFromRect(maxX, maxY, core.minX, core.minY, core.maxX, core.maxY));
		return maxDistance;
	}

	private CoreRect getCoreRect(int minX, int minY, int maxX, int maxY)
	{
		return new CoreRect(
			(minX + maxX) / 2,
			(minY + maxY) / 2,
			(minX + maxX + 1) / 2,
			(minY + maxY + 1) / 2
		);
	}

	private int distanceFromRect(int x, int y, int minX, int minY, int maxX, int maxY)
	{
		int dx = 0;

		if (x < minX)
		{
			dx = minX - x;
		}
		else if (x > maxX)
		{
			dx = x - maxX;
		}

		int dy = 0;

		if (y < minY)
		{
			dy = minY - y;
		}
		else if (y > maxY)
		{
			dy = y - maxY;
		}

		return Math.max(dx, dy);
	}

	private static class CoreRect
	{
		private final int minX;
		private final int minY;
		private final int maxX;
		private final int maxY;

		private CoreRect(int minX, int minY, int maxX, int maxY)
		{
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
		}
	}
}

package com.objectnamemarker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

class ObjectNameMarkerPanel extends PluginPanel
{
	private final ConfigSetList configSets;
	private final ObjectIdSelections selections;
	private final ColorPickerManager colorPickerManager;
	private final ConfigSetHost host;
	private final JComboBox<String> setsCombo = new JComboBox<>();
	private final JButton deleteButton = new JButton("Delete");
	private final JPanel form = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private final Map<HighlightKind, JPanel> lists = new EnumMap<>(HighlightKind.class);
	private final Map<HighlightKind, JTextArea> areas = new EnumMap<>(HighlightKind.class);
	private final EnumSet<HighlightKind> dirtyKinds = EnumSet.noneOf(HighlightKind.class);
	private final Consumer<ObjectIdSelections.Change> listener = this::onSelectionChange;

	private JTextField nameField;
	private ConfigSet editingSet;
	private boolean nameDirty;
	private boolean updating;
	private boolean flushing;

	ObjectNameMarkerPanel(
		ConfigSetList configSets,
		ObjectIdSelections selections,
		ColorPickerManager colorPickerManager,
		ConfigSetHost host
	)
	{
		super();
		this.configSets = configSets;
		this.selections = selections;
		this.colorPickerManager = colorPickerManager;
		this.host = host;

		JLabel help = new JLabel("<html>All sets highlight at once, in list order. Uncheck an ID to hide it for this set only. An ID list resets when its names change.</html>");
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		help.setPreferredSize(new Dimension(PANEL_WIDTH - 24, 48));
		add(help);

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		setsCombo.setToolTipText("Config set to edit");
		setsCombo.addActionListener(event -> onSetSelected());
		row.add(setsCombo, BorderLayout.CENTER);

		JButton addButton = new JButton("+");
		addButton.setToolTipText("Add config set");
		addButton.addActionListener(event -> addSet());
		deleteButton.setToolTipText("Delete config set");
		deleteButton.addActionListener(event -> deleteSet());

		JPanel buttons = new JPanel(new BorderLayout(4, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(addButton, BorderLayout.WEST);
		buttons.add(deleteButton, BorderLayout.CENTER);
		row.add(buttons, BorderLayout.EAST);
		add(row);

		form.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(form);

		selections.addListener(listener);
		reloadFromModel();
	}

	void dispose()
	{
		selections.removeListener(listener);
	}

	void reloadFromModel()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::reloadFromModel);
			return;
		}

		dirtyKinds.clear();
		nameDirty = false;
		reloadCombo();
		rebuildForm();
	}

	private void onSetSelected()
	{
		if (updating)
		{
			return;
		}

		int next = setsCombo.getSelectedIndex();

		if (next < 0 || next == configSets.getSelectedIndex())
		{
			return;
		}

		flushEdits();
		configSets.setSelectedIndex(next);
		rebuildForm();
	}

	private void addSet()
	{
		flushEdits();
		configSets.addSet();
		reloadCombo();
		rebuildForm();
		host.save();
	}

	private void deleteSet()
	{
		ConfigSet selected = configSets.getSelected();

		if (selected == null)
		{
			return;
		}

		int result = JOptionPane.showConfirmDialog(
			this,
			"Delete " + displayName(selected.getName()) + "?",
			"Delete config set",
			JOptionPane.YES_NO_OPTION
		);

		if (result != JOptionPane.YES_OPTION)
		{
			return;
		}

		String removedId = selected.getId();
		dirtyKinds.clear();
		nameDirty = false;
		configSets.removeSelected();
		reloadCombo();
		rebuildForm();
		host.removeSet(removedId);
	}

	private void reloadCombo()
	{
		boolean wasUpdating = updating;
		updating = true;
		setsCombo.removeAllItems();

		for (ConfigSet set : configSets.getSets())
		{
			setsCombo.addItem(displayName(set.getName()));
		}

		int selected = configSets.getSelectedIndex();

		if (selected >= 0 && selected < setsCombo.getItemCount())
		{
			setsCombo.setSelectedIndex(selected);
		}

		deleteButton.setEnabled(configSets.getSelected() != null);
		updating = wasUpdating;
	}

	private void rebuildForm()
	{
		boolean wasUpdating = updating;
		updating = true;
		form.removeAll();
		lists.clear();
		areas.clear();
		nameField = null;
		editingSet = configSets.getSelected();
		ConfigSet set = editingSet;

		if (set == null)
		{
			JLabel empty = new JLabel("No config sets");
			empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			form.add(empty);
			finishForm(wasUpdating);
			return;
		}

		JCheckBox enabled = new JCheckBox("Enabled", set.isEnabled());
		enabled.setOpaque(false);
		enabled.setForeground(Color.WHITE);
		enabled.setToolTipText("Turn highlighting for this set on or off");
		enabled.addActionListener(event ->
		{
			if (updating)
			{
				return;
			}

			flushEdits();
			set.setEnabled(enabled.isSelected());
			host.saveAndRescan(null, EnumSet.noneOf(HighlightKind.class));
		});
		form.add(enabled);

		form.add(label("Name"));
		nameField = new JTextField(set.getName());
		nameField.setForeground(Color.WHITE);
		nameField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		nameField.setCaretColor(Color.WHITE);
		nameField.getDocument().addDocumentListener(listener(() ->
		{
			if (!updating)
			{
				nameDirty = true;
				refreshComboLabel();
			}
		}));
		nameField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent event)
			{
				flushEdits();
			}
		});
		form.add(nameField);

		for (HighlightKind kind : HighlightKind.values())
		{
			addKindSection(set, kind);
		}

		form.add(label("Border width"));
		JSpinner thickness = new JSpinner(new SpinnerNumberModel(set.getBorderThickness(), 1, 100, 1));
		thickness.addChangeListener(event ->
		{
			if (updating)
			{
				return;
			}

			set.setBorderThickness((Integer) thickness.getValue());
			host.save();
		});
		form.add(thickness);

		JCheckBox fade = new JCheckBox("Fade tile opacity", set.isFadeTileOpacity());
		fade.setOpaque(false);
		fade.setForeground(Color.WHITE);
		fade.addActionListener(event ->
		{
			if (updating)
			{
				return;
			}

			set.setFadeTileOpacity(fade.isSelected());
			host.save();
		});
		form.add(fade);
		finishForm(wasUpdating);
	}

	private void finishForm(boolean wasUpdating)
	{
		form.revalidate();
		form.repaint();
		revalidate();
		repaint();
		updating = wasUpdating;
	}

	private void addKindSection(ConfigSet set, HighlightKind kind)
	{
		form.add(label(kind.getTitle()));
		JTextArea area = new JTextArea(namesFor(set, kind), 3, 12);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setForeground(Color.WHITE);
		area.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		area.setCaretColor(Color.WHITE);
		area.setToolTipText("Supports commas, new lines, and # comments.");
		area.getDocument().addDocumentListener(listener(() ->
		{
			if (!updating)
			{
				dirtyKinds.add(kind);
			}
		}));
		area.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent event)
			{
				flushEdits();
			}
		});
		areas.put(kind, area);

		JScrollPane scroll = new JScrollPane(area);
		scroll.setPreferredSize(new Dimension(PANEL_WIDTH - 24, 58));
		form.add(scroll);
		form.add(colorControls(set, kind));

		JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		lists.put(kind, list);
		form.add(list);
		rebuildIds(kind);
	}

	private JPanel colorControls(ConfigSet set, HighlightKind kind)
	{
		JPanel colors = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		colors.setBackground(ColorScheme.DARK_GRAY_COLOR);

		switch (kind)
		{
			case HULL:
				colors.add(colorSwatch("Hull colour", set::getHullColor, set::setHullColor));
				break;
			case OUTLINE:
				colors.add(colorSwatch("Outline colour", set::getOutlineColor, set::setOutlineColor));
				break;
			case TILE:
				colors.add(colorSwatch("Tile fill colour", set::getTileFillColor, set::setTileFillColor));
				colors.add(colorSwatch("Tile border colour", set::getTileBorderColor, set::setTileBorderColor));
				break;
			default:
				break;
		}

		return colors;
	}

	private JPanel colorSwatch(String title, Supplier<Color> current, Consumer<Color> apply)
	{
		JPanel swatch = new JPanel(new BorderLayout());
		paintSwatch(swatch, null, current.get());
		swatch.setPreferredSize(new Dimension(PANEL_WIDTH - 24, 22));
		swatch.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		swatch.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		swatch.setToolTipText(title);

		JLabel text = new JLabel(title);
		text.setHorizontalAlignment(SwingConstants.CENTER);
		text.setForeground(textColor(swatch.getBackground()));
		swatch.add(text, BorderLayout.CENTER);
		swatch.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent event)
			{
				RuneliteColorPicker picker = colorPickerManager.create(swatch, current.get(), title, false);
				picker.setOnColorChange(next ->
				{
					apply.accept(next);
					paintSwatch(swatch, text, next);
				});
				picker.setOnClose(next -> host.save());
				picker.setVisible(true);
			}
		});
		return swatch;
	}

	private void paintSwatch(JPanel swatch, JLabel text, Color color)
	{
		Color shown = swatchColor(color);
		swatch.setBackground(shown);

		if (text != null)
		{
			text.setForeground(textColor(shown));
		}

		swatch.repaint();
	}

	private void onSelectionChange(ObjectIdSelections.Change change)
	{
		ConfigSet selected = configSets.getSelected();

		if (selected == null || !selected.getId().equals(change.setId))
		{
			return;
		}

		rebuildIds(change.kind);
	}

	private void rebuildIds(HighlightKind kind)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> rebuildIds(kind));
			return;
		}

		JPanel list = lists.get(kind);
		ConfigSet set = editingSet;

		if (list == null || set == null)
		{
			return;
		}

		list.removeAll();
		List<ObjectIdSelections.Entry> entries = selections.entries(set.getId(), kind, set.hiddenIds(kind));

		if (entries.isEmpty())
		{
			JLabel empty = new JLabel("No matching objects yet");
			empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			list.add(empty);
		}
		else
		{
			for (ObjectIdSelections.Entry entry : entries)
			{
				list.add(createCheckbox(set, kind, entry));
			}
		}

		list.revalidate();
		list.repaint();
		revalidate();
		repaint();
	}

	private JCheckBox createCheckbox(ConfigSet set, HighlightKind kind, ObjectIdSelections.Entry entry)
	{
		JCheckBox checkbox = new JCheckBox(entry.id + "  " + entry.name);
		checkbox.setOpaque(false);
		checkbox.setForeground(Color.WHITE);
		checkbox.setSelected(entry.displayed);
		checkbox.setToolTipText("Show " + entry.name + " (" + entry.id + ") for this set");
		checkbox.addActionListener(event ->
		{
			set.setDisplayed(kind, entry.id, checkbox.isSelected());
			host.save();
		});
		return checkbox;
	}

	private void flushEdits()
	{
		if (flushing || updating || editingSet == null)
		{
			return;
		}

		ConfigSet set = editingSet;
		EnumSet<HighlightKind> dirty = EnumSet.noneOf(HighlightKind.class);
		dirty.addAll(dirtyKinds);
		dirtyKinds.clear();
		boolean saveName = nameDirty;
		nameDirty = false;

		if (dirty.isEmpty() && !saveName)
		{
			return;
		}

		flushing = true;

		try
		{
			EnumSet<HighlightKind> changed = EnumSet.noneOf(HighlightKind.class);

			for (HighlightKind kind : dirty)
			{
				JTextArea area = areas.get(kind);

				if (area == null)
				{
					continue;
				}

				String text = area.getText();

				if (!text.equals(namesFor(set, kind)))
				{
					setNames(set, kind, text);
					set.clearHidden(kind);
					changed.add(kind);
				}
			}

			if (saveName && nameField != null && !nameField.getText().equals(set.getName()))
			{
				set.setName(nameField.getText());
				saveName = true;
			}
			else
			{
				saveName = false;
			}

			if (!changed.isEmpty())
			{
				host.saveAndRescan(set.getId(), changed);
			}
			else if (saveName)
			{
				host.save();
			}
		}
		finally
		{
			flushing = false;
		}
	}

	private void refreshComboLabel()
	{
		if (nameField == null || editingSet == null)
		{
			return;
		}

		int index = configSets.indexOf(editingSet);

		if (index < 0)
		{
			return;
		}

		boolean wasUpdating = updating;
		updating = true;
		setsCombo.removeItemAt(index);
		setsCombo.insertItemAt(displayName(nameField.getText()), index);
		setsCombo.setSelectedIndex(index);
		updating = wasUpdating;
	}

	private static String namesFor(ConfigSet set, HighlightKind kind)
	{
		switch (kind)
		{
			case HULL:
				return set.getHullObjectNames();
			case OUTLINE:
				return set.getOutlineObjectNames();
			case TILE:
				return set.getTileObjectNames();
			default:
				return "";
		}
	}

	private static void setNames(ConfigSet set, HighlightKind kind, String text)
	{
		switch (kind)
		{
			case HULL:
				set.setHullObjectNames(text);
				break;
			case OUTLINE:
				set.setOutlineObjectNames(text);
				break;
			case TILE:
				set.setTileObjectNames(text);
				break;
			default:
				break;
		}
	}

	private static JLabel label(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		return label;
	}

	private static String displayName(String name)
	{
		if (name == null || name.trim().isEmpty())
		{
			return "Config set";
		}

		return name;
	}

	private static Color swatchColor(Color color)
	{
		Color base = ColorScheme.DARKER_GRAY_COLOR;
		float alpha = color.getAlpha() / 255f;
		int red = Math.round(color.getRed() * alpha + base.getRed() * (1f - alpha));
		int green = Math.round(color.getGreen() * alpha + base.getGreen() * (1f - alpha));
		int blue = Math.round(color.getBlue() * alpha + base.getBlue() * (1f - alpha));
		return new Color(red, green, blue);
	}

	private static Color textColor(Color background)
	{
		int luminance = background.getRed() * 2 + background.getGreen() * 3 + background.getBlue();
		return luminance > 700 ? Color.BLACK : Color.WHITE;
	}

	private static DocumentListener listener(Runnable update)
	{
		return new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent event)
			{
				update.run();
			}

			@Override
			public void removeUpdate(DocumentEvent event)
			{
				update.run();
			}

			@Override
			public void changedUpdate(DocumentEvent event)
			{
				update.run();
			}
		};
	}
}

package com.objectnamemarker;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

class ObjectNameMarkerParser
{
    private static final Pattern LEGACY_TILE_SUFFIX = Pattern.compile("[1-9]\\d*");

    static Set<String> parseNames(String input)
    {
        Set<String> names = new HashSet<>();

        for (String token : tokens(input))
        {
            String name = normalizeName(token);

            if (!name.isEmpty())
            {
                names.add(name);
            }
        }

        return names;
    }

    static Set<String> parseTileNames(String input)
    {
        Set<String> names = new HashSet<>();

        for (String token : tokens(input))
        {
            String name = token;
            int separator = token.lastIndexOf(":");

            // Keep legacy name:<positive number> configs working after tile expansion was removed.
            // The number is accepted for compatibility only and never affects rendering.
            if (separator >= 0
                    && LEGACY_TILE_SUFFIX.matcher(token.substring(separator + 1).trim()).matches())
            {
                name = token.substring(0, separator);
            }

            String normalizedName = normalizeName(name);

            if (!normalizedName.isEmpty())
            {
                names.add(normalizedName);
            }
        }

        return names;
    }

    static String normalizeName(String name)
    {
        if (name == null)
        {
            return "";
        }

        return name.trim().toLowerCase();
    }

    private static Set<String> tokens(String input)
    {
        Set<String> tokens = new HashSet<>();

        if (input == null || input.trim().isEmpty())
        {
            return tokens;
        }

        for (String rawLine : input.split("\\R"))
        {
            String line = rawLine.trim();

            int commentIndex = line.indexOf("#");
            if (commentIndex >= 0)
            {
                line = line.substring(0, commentIndex).trim();
            }

            if (line.isEmpty())
            {
                continue;
            }

            for (String token : line.split(","))
            {
                String trimmed = token.trim();

                if (!trimmed.isEmpty())
                {
                    tokens.add(trimmed);
                }
            }
        }

        return tokens;
    }
}

