@PluginDescriptor(
	name = "Super Object Marker",
	description = "Highlight game objects by name with hull, outline, and tile highlights",
	tags = {"object", "marker", "highlight", "name", "tile"}
)
public class ObjectNameMarkerPlugin extends Plugin implements ConfigSetHost
{
	private static final Logger log = Logger.getLogger(ObjectNameMarkerPlugin.class.getName());
	private static final String CONFIG_GROUP = "objectnamemarker";
	private static final String CONFIG_SETS_KEY = "configSets";
	private static final BufferedImage ICON = createIcon();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ColorPickerManager colorPickerManager;

	@Inject
	private Gson gson;

	@Inject
	private ObjectNameMarkerOverlay overlay;

	@Inject
	private ObjectNameMarkerConfig config;

	private final Set<TileObject> objects = new HashSet<>();
	private final ObjectIdSelections selections = new ObjectIdSelections();
	private final ConfigSetList configSets = new ConfigSetList();
	private ObjectNameMarkerPanel panel;
	private NavigationButton navButton;
	private String lastWritten = "";

	@Provides
	ObjectNameMarkerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ObjectNameMarkerConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadSets();
		panel = new ObjectNameMarkerPanel(configSets, selections, colorPickerManager, this);
		navButton = NavigationButton.builder()
			.tooltip("Super Object Marker")
			.icon(ICON)
			.priority(0)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		clientThread.invoke(this::reloadObjects);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		if (panel != null)
		{
			panel.dispose();
			panel = null;
		}

		objects.clear();
		selections.clear();
	}

	@Override
	public void save()
	{
		String json = ConfigSetCodec.write(gson, configSets.getSelectedIndex(), configSets.snapshot());
		lastWritten = json;
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_SETS_KEY, json);
	}

	@Override
	public void saveAndRescan(String setId, Set<HighlightKind> resetKinds)
	{
		save();
		EnumSet<HighlightKind> kinds = EnumSet.noneOf(HighlightKind.class);

		if (resetKinds != null)
		{
			kinds.addAll(resetKinds);
		}

		EnumSet<HighlightKind> kindsCopy = kinds;
		clientThread.invoke(() -> applyScene(setId, kindsCopy));
	}

	@Override
	public void removeSet(String setId)
	{
		save();
		clientThread.invoke(() ->
		{
			selections.removeSet(setId);
			applyScene(null, EnumSet.noneOf(HighlightKind.class));
		});
	}

	Set<TileObject> getObjects()
	{
		return objects;
	}

	List<ConfigSet> getConfigSets()
	{
		return configSets.getSets();
	}

	NamedObject identify(TileObject object)
	{
		if (object == null)
		{
			return null;
		}

		ObjectComposition composition = client.getObjectDefinition(object.getId());

		if (composition == null)
		{
			return null;
		}

		try
		{
			ObjectComposition impostor = composition.getImpostor();

			if (impostor != null)
			{
				composition = impostor;
			}
		}
		catch (RuntimeException ignored)
		{
			// Some objects do not have a valid impostor/transform state.
		}

		String name = composition.getName();

		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return null;
		}

		String displayName = Text.removeTags(name).trim();

		if (displayName.isEmpty() || "null".equalsIgnoreCase(displayName))
		{
			return null;
		}

		// Use the placed object id so transformed lookalikes stay separate from the definition they resemble.
		return new NamedObject(object.getId(), ObjectNameMarkerParser.normalizeName(displayName), displayName);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()) || !CONFIG_SETS_KEY.equals(event.getKey()))
		{
			return;
		}

		String incoming = config.configSets();

		if (incoming == null || incoming.equals(lastWritten))
		{
			return;
		}

		loadStored(incoming);
		ObjectNameMarkerPanel currentPanel = panel;

		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(currentPanel::reloadFromModel);
		}

		clientThread.invoke(() ->
		{
			selections.clear();
			applyScene(null, EnumSet.noneOf(HighlightKind.class));
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			objects.clear();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		checkObjectAndNotify(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objects.remove(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		checkObjectAndNotify(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		objects.remove(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		checkObjectAndNotify(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		objects.remove(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		checkObjectAndNotify(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objects.remove(event.getGroundObject());
	}

	private void loadSets()
	{
		String stored = configManager.getConfiguration(CONFIG_GROUP, CONFIG_SETS_KEY);

		if (stored == null || stored.trim().isEmpty())
		{
			ConfigSet migrated = ConfigSetCodec.fromLegacy(
				configManager.getConfiguration(CONFIG_GROUP, "hullObjectNames"),
				configManager.getConfiguration(CONFIG_GROUP, "outlineObjectNames"),
				configManager.getConfiguration(CONFIG_GROUP, "tileObjectNames"),
				configManager.getConfiguration(CONFIG_GROUP, "hullColor"),
				configManager.getConfiguration(CONFIG_GROUP, "outlineColor"),
				configManager.getConfiguration(CONFIG_GROUP, "tileFillColor"),
				configManager.getConfiguration(CONFIG_GROUP, "tileBorderColor"),
				configManager.getConfiguration(CONFIG_GROUP, "borderThickness"),
				configManager.getConfiguration(CONFIG_GROUP, "fadeTileOpacity")
			);
			configSets.replace(Collections.singletonList(migrated), 0);
			save();
			return;
		}

		loadStored(stored);
	}

	private void loadStored(String stored)
	{
		try
		{
			ConfigSetCodec.Loaded loaded = ConfigSetCodec.read(gson, stored);
			configSets.replace(loaded.sets, loaded.selectedIndex);
			lastWritten = stored;
		}
		catch (RuntimeException ex)
		{
			log.log(Level.WARNING, "Could not read config sets", ex);
			configSets.replace(Collections.singletonList(ConfigSet.createDefault("Config set 1")), 0);
			save();
		}
	}

	private void reloadObjects()
	{
		Set<ObjectIdSelections.Change> discovered = rebuildObjects();

		for (ConfigSet set : configSets.getSets())
		{
			for (HighlightKind kind : HighlightKind.values())
			{
				discovered.add(new ObjectIdSelections.Change(set.getId(), kind));
			}
		}

		selections.notifyListeners(discovered);
	}

	private void applyScene(String setId, Set<HighlightKind> resetKinds)
	{
		if (setId != null)
		{
			for (HighlightKind kind : resetKinds)
			{
				selections.reset(setId, kind);
			}
		}

		Set<ObjectIdSelections.Change> discovered = rebuildObjects();

		if (setId != null)
		{
			for (HighlightKind kind : resetKinds)
			{
				discovered.add(new ObjectIdSelections.Change(setId, kind));
			}
		}

		selections.notifyListeners(discovered);
	}

	private Set<ObjectIdSelections.Change> rebuildObjects()
	{
		objects.clear();
		Set<ObjectIdSelections.Change> discovered = new LinkedHashSet<>();

		if (!hasConfiguredMarkers() || client.getGameState() != GameState.LOGGED_IN)
		{
			return discovered;
		}

		Scene scene = client.getScene();
		Tile[][][] tiles = scene.getTiles();

		for (int plane = 0; plane < tiles.length; plane++)
		{
			for (int x = 0; x < tiles[plane].length; x++)
			{
				for (int y = 0; y < tiles[plane][x].length; y++)
				{
					Tile tile = tiles[plane][x][y];

					if (tile == null)
					{
						continue;
					}

					for (GameObject gameObject : tile.getGameObjects())
					{
						checkObject(gameObject, discovered);
					}

					checkObject(tile.getWallObject(), discovered);
					checkObject(tile.getDecorativeObject(), discovered);
					checkObject(tile.getGroundObject(), discovered);
				}
			}
		}

		return discovered;
	}

	private void checkObjectAndNotify(TileObject object)
	{
		Set<ObjectIdSelections.Change> discovered = new LinkedHashSet<>();
		checkObject(object, discovered);

		if (!discovered.isEmpty())
		{
			selections.notifyListeners(discovered);
		}
	}

	private void checkObject(TileObject object, Set<ObjectIdSelections.Change> discovered)
	{
		if (object == null || !hasConfiguredMarkers())
		{
			return;
		}

		NamedObject namedObject = identify(object);

		if (namedObject == null)
		{
			return;
		}

		boolean matched = false;

		for (ConfigSet set : configSets.getSets())
		{
			for (HighlightKind kind : HighlightKind.values())
			{
				if (!set.matches(kind, namedObject.name))
				{
					continue;
				}

				matched = true;

				if (selections.observe(set.getId(), kind, namedObject.id, namedObject.displayName))
				{
					discovered.add(new ObjectIdSelections.Change(set.getId(), kind));
				}
			}
		}

		if (matched)
		{
			objects.add(object);
		}
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(0, 180, 0));
		graphics.fillRoundRect(1, 1, 14, 14, 4, 4);
		graphics.dispose();
		return image;
	}

	private boolean hasConfiguredMarkers()
	{
		for (ConfigSet set : configSets.getSets())
		{
			if (set.hasActiveNames())
			{
				return true;
			}
		}

		return false;
	}
}

package com.objectnamemarker;

import com.google.gson.Gson;
import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ConfigSetCodecTest
{
	private final Gson gson = new Gson();

	@Test
	public void roundTripsSetsColoursHiddenIdsAndSelection()
	{
		ConfigSet trees = ConfigSet.create("trees", "Trees");
		trees.setHullObjectNames("Tree, Oak tree");
		trees.setHullColor(Color.GREEN);
		trees.setOutlineColor(Color.MAGENTA);
		trees.setDisplayed(HighlightKind.HULL, 1276, false);

		ConfigSet flowers = ConfigSet.create("flowers", "Daisies");
		flowers.setEnabled(false);
		flowers.setTileObjectNames("Daisies\n# comment");
		flowers.setTileFillColor(new Color(255, 165, 0, 40));
		flowers.setBorderThickness(3);
		flowers.setFadeTileOpacity(true);

		String json = ConfigSetCodec.write(gson, 1, Arrays.asList(trees, flowers));
		ConfigSetCodec.Loaded loaded = ConfigSetCodec.read(gson, json);

		assertEquals(1, loaded.selectedIndex);
		assertEquals(2, loaded.sets.size());

		ConfigSet first = loaded.sets.get(0);
		assertEquals("trees", first.getId());
		assertEquals("Trees", first.getName());
		assertEquals("Tree, Oak tree", first.getHullObjectNames());
		assertEquals(Color.GREEN.getRGB(), first.getHullColor().getRGB());
		assertEquals(Color.MAGENTA.getRGB(), first.getOutlineColor().getRGB());
		assertFalse(first.isDisplayed(HighlightKind.HULL, 1276));
		assertTrue(first.isDisplayed(HighlightKind.HULL, 1278));
		assertTrue(first.matches(HighlightKind.HULL, "oak tree"));

		ConfigSet second = loaded.sets.get(1);
		assertFalse(second.isEnabled());
		assertEquals("Daisies\n# comment", second.getTileObjectNames());
		assertEquals(new Color(255, 165, 0, 40).getRGB(), second.getTileFillColor().getRGB());
		assertEquals(3, second.getBorderThickness());
		assertTrue(second.isFadeTileOpacity());
		second.setEnabled(true);
		assertTrue(second.matches(HighlightKind.TILE, "daisies"));
	}

	@Test
	public void missingEnabledFlagStaysOn()
	{
		ConfigSetCodec.Loaded loaded = ConfigSetCodec.read(gson, "{\"selected\":0,\"sets\":[{\"name\":\"Trees\",\"hullObjectNames\":\"Tree\"}]}");

		assertEquals(1, loaded.sets.size());
		assertTrue(loaded.sets.get(0).isEnabled());
		assertEquals("Trees", loaded.sets.get(0).getName());
		assertTrue(loaded.sets.get(0).matches(HighlightKind.HULL, "tree"));
		assertEquals(new Color(0, 255, 0, 50).getRGB(), loaded.sets.get(0).getHullColor().getRGB());
	}

	@Test
	public void legacyConfigBecomesOneSet()
	{
		Color hull = new Color(0, 255, 0, 50);
		ConfigSet set = ConfigSetCodec.fromLegacy(
			"Tree, Oak tree",
			"",
			"Daisies",
			Integer.toString(hull.getRGB()),
			Integer.toString(Color.MAGENTA.getRGB()),
			Integer.toString(new Color(255, 165, 0, 40).getRGB()),
			"not-a-color",
			"4",
			"true"
		);

		assertEquals("Config set 1", set.getName());
		assertTrue(set.isEnabled());
		assertEquals("Tree, Oak tree", set.getHullObjectNames());
		assertEquals(hull.getRGB(), set.getHullColor().getRGB());
		assertEquals(Color.MAGENTA.getRGB(), set.getOutlineColor().getRGB());
		assertEquals(new Color(255, 165, 0, 40).getRGB(), set.getTileFillColor().getRGB());
		assertEquals(new Color(0, 255, 0, 0).getRGB(), set.getTileBorderColor().getRGB());
		assertEquals(4, set.getBorderThickness());
		assertTrue(set.isFadeTileOpacity());
		assertTrue(set.matches(HighlightKind.HULL, "tree"));
		assertTrue(set.matches(HighlightKind.TILE, "daisies"));
	}

	@Test
	public void blankLegacyValuesUseDefaults()
	{
		ConfigSet set = ConfigSetCodec.fromLegacy(null, null, null, null, null, null, null, null, null);

		assertEquals("", set.getHullObjectNames());
		assertEquals(1, set.getBorderThickness());
		assertFalse(set.isFadeTileOpacity());
		assertEquals(new Color(0, 255, 0).getRGB(), set.getOutlineColor().getRGB());
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsBrokenJson()
	{
		ConfigSetCodec.read(gson, "{");
	}

	@Test
	public void emptySetListIsValid()
	{
		ConfigSetCodec.Loaded loaded = ConfigSetCodec.read(gson, "{\"selected\":3,\"sets\":[]}");

		assertTrue(loaded.sets.isEmpty());
		assertEquals(3, loaded.selectedIndex);
	}

	@Test
	public void quotesAndNewlinesSurvive()
	{
		ConfigSet set = ConfigSet.createDefault("Config set 1");
		set.setHullObjectNames("Tree \"oak\"\nnext");
		ConfigSetCodec.Loaded loaded = ConfigSetCodec.read(gson, ConfigSetCodec.write(gson, 0, Collections.singletonList(set)));

		assertEquals("Tree \"oak\"\nnext", loaded.sets.get(0).getHullObjectNames());
	}
}

package com.objectnamemarker;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ConfigSetListTest
{
	@Test
	public void plusAppendsANumberedSetAndDeleteSelectsTheNeighbour()
	{
		ConfigSetList list = new ConfigSetList();
		list.replace(Collections.emptyList(), -1);

		ConfigSet first = list.addSet();
		assertEquals("Config set 1", first.getName());
		assertEquals(0, list.getSelectedIndex());

		ConfigSet second = list.addSet();
		assertEquals("Config set 2", second.getName());
		assertEquals(1, list.getSelectedIndex());

		assertEquals(second, list.removeSelected());
		assertEquals(first, list.getSelected());

		assertEquals(first, list.removeSelected());
		assertNull(list.getSelected());
		assertEquals(-1, list.getSelectedIndex());
	}

	@Test
	public void nextNameSkipsLabelsStillInUse()
	{
		ConfigSet renamed = ConfigSet.createDefault("Trees");
		ConfigSet second = ConfigSet.createDefault("Config set 2");

		assertEquals("Config set 1", ConfigSetList.nextName(java.util.Arrays.asList(renamed, second)));
	}
}

package com.objectnamemarker;

import java.awt.Color;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class HighlightPlanTest
{
	@Test
	public void overlappingSetsAllDrawInListOrder()
	{
		ConfigSet trees = set("Trees", true);
		trees.setHullObjectNames("Tree");
		trees.setHullColor(Color.GREEN);

		ConfigSet alsoTrees = set("Also trees", true);
		alsoTrees.setHullObjectNames("Tree");
		alsoTrees.setHullColor(Color.MAGENTA);

		List<HighlightPlan.Draw> draws = HighlightPlan.plan(Arrays.asList(trees, alsoTrees), "tree", 1276);

		assertEquals(2, draws.size());
		assertEquals("Trees", draws.get(0).set.getName());
		assertEquals(HighlightKind.HULL, draws.get(0).kind);
		assertEquals(Color.GREEN.getRGB(), draws.get(0).set.getHullColor().getRGB());
		assertEquals("Also trees", draws.get(1).set.getName());
		assertEquals(Color.MAGENTA.getRGB(), draws.get(1).set.getHullColor().getRGB());
	}

	@Test
	public void uncheckingAnIdHidesThatSetOnly()
	{
		ConfigSet trees = set("Trees", true);
		trees.setHullObjectNames("Tree");
		trees.setHullColor(Color.GREEN);
		trees.setDisplayed(HighlightKind.HULL, 1276, false);

		ConfigSet alsoTrees = set("Also trees", true);
		alsoTrees.setHullObjectNames("Tree");
		alsoTrees.setHullColor(Color.MAGENTA);

		List<HighlightPlan.Draw> draws = HighlightPlan.plan(Arrays.asList(trees, alsoTrees), "tree", 1276);

		assertEquals(1, draws.size());
		assertEquals("Also trees", draws.get(0).set.getName());
		assertEquals(HighlightKind.HULL, draws.get(0).kind);
	}

	@Test
	public void disabledSetIsSkippedAndOtherKindsStillDraw()
	{
		ConfigSet trees = set("Trees", false);
		trees.setHullObjectNames("Tree");

		ConfigSet flowers = set("Daisies", true);
		flowers.setOutlineObjectNames("Tree");
		flowers.setTileObjectNames("Tree");

		List<HighlightPlan.Draw> draws = HighlightPlan.plan(Arrays.asList(trees, flowers), "tree", 1276);

		assertEquals(2, draws.size());
		assertEquals(HighlightKind.OUTLINE, draws.get(0).kind);
		assertEquals(HighlightKind.TILE, draws.get(1).kind);
		assertEquals("Daisies", draws.get(0).set.getName());
	}

	private static ConfigSet set(String name, boolean enabled)
	{
		ConfigSet set = ConfigSet.createDefault(name);
		set.setEnabled(enabled);
		return set;
	}
}

package com.objectnamemarker;

import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ObjectIdSelectionsTest
{
	private static final String SET = "set-1";
	private static final String OTHER = "set-2";

	@Test
	public void newIdsAreDisplayedUntilHidden()
	{
		ObjectIdSelections selections = new ObjectIdSelections();

		assertTrue(selections.observe(SET, HighlightKind.HULL, 1276, "Tree"));
		assertFalse(selections.observe(SET, HighlightKind.HULL, 1276, "Tree"));

		List<ObjectIdSelections.Entry> shown = selections.entries(SET, HighlightKind.HULL, Collections.emptySet());
		assertEquals(1, shown.size());
		assertTrue(shown.get(0).displayed);

		List<ObjectIdSelections.Entry> hidden = selections.entries(SET, HighlightKind.HULL, Collections.singleton(1276));
		assertFalse(hidden.get(0).displayed);
		assertFalse(selections.observe(SET, HighlightKind.HULL, 1276, "Tree"));
	}

	@Test
	public void resetClearsIdsForThatSetAndListOnly()
	{
		ObjectIdSelections selections = new ObjectIdSelections();
		selections.observe(SET, HighlightKind.HULL, 1276, "Tree");
		selections.observe(SET, HighlightKind.TILE, 1278, "Tree");
		selections.observe(OTHER, HighlightKind.HULL, 1276, "Tree");

		selections.reset(SET, HighlightKind.HULL);

		assertTrue(selections.entries(SET, HighlightKind.HULL, Collections.emptySet()).isEmpty());
		assertEquals(1, selections.entries(SET, HighlightKind.TILE, Collections.emptySet()).size());
		assertEquals(1, selections.entries(OTHER, HighlightKind.HULL, Collections.emptySet()).size());

		assertTrue(selections.observe(SET, HighlightKind.HULL, 1276, "Tree"));
	}

	@Test
	public void entriesShowNamesAndIdsSortedByNameThenId()
	{
		ObjectIdSelections selections = new ObjectIdSelections();
		selections.observe(SET, HighlightKind.OUTLINE, 1280, "Tree");
		selections.observe(SET, HighlightKind.OUTLINE, 1276, "Tree");
		selections.observe(SET, HighlightKind.OUTLINE, 10820, "Oak");

		List<ObjectIdSelections.Entry> entries = selections.entries(
			SET,
			HighlightKind.OUTLINE,
			Collections.singleton(1280)
		);

		assertEquals(3, entries.size());
		assertEquals(10820, entries.get(0).id);
		assertEquals("Oak", entries.get(0).name);
		assertTrue(entries.get(0).displayed);
		assertEquals(1276, entries.get(1).id);
		assertEquals("Tree", entries.get(1).name);
		assertTrue(entries.get(1).displayed);
		assertEquals(1280, entries.get(2).id);
		assertEquals("Tree", entries.get(2).name);
		assertFalse(entries.get(2).displayed);
	}
}

package com.objectnamemarker;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ObjectNameMarkerParserTest
{
    @Test
    public void stripsLegacyPositiveNumericSuffixesFromTileNames()
    {
        assertEquals(
                Collections.singleton("bank booth"),
                ObjectNameMarkerParser.parseTileNames(
                        "Bank booth:1, Bank booth:2, Bank booth:3, Bank booth:999999999999999999999"
                )
        );
    }

    @Test
    public void leavesNonPositiveAndNonNumericSuffixesAsPartOfTheName()
    {
        assertEquals(
                new HashSet<>(Arrays.asList("bank booth:0", "bank booth:-1", "bank booth:custom")),
                ObjectNameMarkerParser.parseTileNames("Bank booth:0, Bank booth:-1, Bank booth:custom")
        );
    }
}

